    ["nombre" =&gt; "Cable USB", "precio" =&gt; 5.0,   "stock" =&gt; 30],
];

// a) Con BREAK: lista productos hasta encontrar el primero con stock = 0
//    Al encontrarlo, muestra "Agotado: {nombre}" y para.
echo "--- Con BREAK ---\n";
foreach ...

// b) Con CONTINUE: muestra solo los productos con precio &lt;= 50 €
